import java.util.*; class Solution { public int[][] outerTrees(int[][] trees) { int n = trees.length; if (n <= 2) return trees; Arrays.sort(trees, (a, b) -> a[0] != b[0] ? a[0] - b[0] : a[1] - b[1]); List<int[]> hull = new ArrayList<>(); for (int i = 0; i < n; i++) { while (hull.size() >= 2 && crossProduct(hull.get(hull.size() - 2), hull.get(hull.size() - 1), trees[i]) < 0) { hull.remove(hull.size() - 1); } hull.add(trees[i]); } int lowerHullSize = hull.size(); for (int i = n - 2; i >= 0; i--) { while (hull.size() > lowerHullSize && crossProduct(hull.get(hull.size() - 2), hull.get(hull.size() - 1), trees[i]) < 0) { hull.remove(hull.size() - 1); } hull.add(trees[i]); } hull.remove(hull.size() - 1); Set<String> set = new HashSet<>(); List<int[]> result = new ArrayList<>(); for (int[] p : hull) { String key = p[0] + "," + p[1]; if (!set.contains(key)) { result.add(p); set.add(key); } } return result.toArray(new int[result.size()][]); } private int crossProduct(int[] a, int[] b, int[] c) { return (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]); } }